/**
 * exampilot-welcome(-staging): public landing page + application portal.
 * NOT behind Access. Serves only: the landing page, the portal pages, static images
 * and /api/public/*. It shares the D1 database with the learning Worker but can
 * reach nothing else (no bank, no learning API).
 */
import { handlePublic } from '../platform/public'
import type { PlatformEnv } from '../platform/util'
// generated by tools/web/build-welcome.mjs
import { PAGES } from './pages.generated.js'

const BASE = {
  'X-Robots-Tag': 'noindex, nofollow, noarchive',
  'Referrer-Policy': 'no-referrer',
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Strict-Transport-Security': 'max-age=31536000',
  'Cross-Origin-Opener-Policy': 'same-origin',
  'Permissions-Policy': 'geolocation=(), microphone=(), camera=(), payment=(), usb=()',
}
const CSP_LANDING =
  "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
const CSP_PORTAL =
  "default-src 'none'; script-src 'self' https://challenges.cloudflare.com; frame-src https://challenges.cloudflare.com; connect-src 'self'; img-src 'self'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"

type Page = { type: string; body: string; b64?: boolean; csp?: string; cache?: string }
const pages = PAGES as Record<string, Page>

function b64(s: string) {
  const b = atob(s)
  const u = new Uint8Array(b.length)
  for (let i = 0; i < b.length; i++) u[i] = b.charCodeAt(i)
  return u
}

export default {
  async fetch(req: Request, env: PlatformEnv, ctx?: { waitUntil(p: Promise<unknown>): void }): Promise<Response> {
    const u = new URL(req.url)
    // www.<apex> → <apex> (production only binds www to this Worker for this redirect)
    if (u.hostname.startsWith('www.')) {
      u.hostname = u.hostname.slice(4)
      return new Response(null, { status: 301, headers: { Location: u.toString(), ...BASE } })
    }
    if (u.pathname.startsWith('/api/public/')) {
      const r = await handlePublic(req, env, { waitUntil: ctx ? (p) => ctx.waitUntil(p) : undefined })
      const h = new Headers(r.headers)
      for (const [k, v] of Object.entries(BASE)) h.set(k, v)
      h.set('Content-Security-Policy', "default-src 'none'; frame-ancestors 'none'")
      return new Response(r.body, { status: r.status, headers: h })
    }
    if (req.method !== 'GET' && req.method !== 'HEAD')
      return new Response('Method Not Allowed', { status: 405, headers: BASE })
    let p = u.pathname
    if (p === '/join') return Response.redirect(u.origin + '/apply' + u.search, 302)
    if (p === '/index.html') p = '/'
    if (['/apply', '/status', '/invite', '/account'].includes(p.replace(/\/$/, ''))) p = '/portal.html'
    const pg = pages[p]
    if (!pg) return Response.redirect(u.origin + '/', 302)
    const body = pg.b64 ? b64(pg.body) : pg.body
    const headers: Record<string, string> = {
      ...BASE,
      'Content-Type': pg.type,
      'Cache-Control': pg.cache || 'no-cache, must-revalidate',
    }
    if (pg.type.startsWith('text/html'))
      headers['Content-Security-Policy'] = p === '/portal.html' ? CSP_PORTAL : CSP_LANDING
    return new Response(req.method === 'HEAD' ? null : body, { headers })
  },
}
